    INSERT INTO dbo.T_Arts (
        Id_Article, Id_Marque, Id_Type, Id_Category, Id_Mesure,
        Description, Description_I, Description_II, Description_III,
        Price, Qte, Id_Monais, Soeuil, Internal, Can_Insert_After_0,
        [User], DateSys, Cumputer, isTransferable
    )
    SELECT
        N'MKL250', 1, 1,
        c.Id_Category, 1,
        N'Burberry London chemise', NULL, NULL, NULL,
        70250, 0, 2, 0, 0, 1,
        N'IMPORT', CAST('2026-09-17' AS DATE), N'MALAIKA-IMPORT', 1
    FROM dbo.T_Art_Categorys c WHERE c.Description_Category = N'Textiles et Vêtements';

    IF NOT EXISTS (SELECT 1 FROM dbo.T_Stock WHERE Id_Article = N'MKL250' AND Id_Localisation = 1)
        INSERT INTO dbo.T_Stock (Id_Article, Id_Localisation, Qte, Seuil, Qte_max, CodeBar, DateSys, UserLogin)
        VALUES (N'MKL250', 1, 0, 0, 100, N'MKL250', CAST('2026-09-17' AS DATE), N'IMPORT');
END
ELSE
BEGIN
    UPDATE a SET
        a.Id_Category = c.Id_Category,
        a.Description = N'Burberry London chemise',
        a.Description_I = NULL,
        a.Description_II = NULL,
        a.Description_III = NULL,
        a.Price = 70250,
        a.Id_Monais = 2,
        a.Id_Type = 1
    FROM dbo.T_Arts a
    INNER JOIN dbo.T_Art_Categorys c ON c.Description_Category = N'Textiles et Vêtements'
    WHERE a.Id_Article = N'MKL250';
END
